const galeryBox = document.querySelector('.gallery');
const markup = images
  .map(({ preview, original, description }) => {
    return `<li class="gallery-item">
	<a class="gallery-link" href="${original}">
		<img
		  class="gallery-image"
		  src="${preview}"
		  alt="${description}"
		/>
	</a>
</li>`;
  })
  .join('');
const createMarkup = galeryBox.insertAdjacentHTML('afterbegin', markup);
let gallery = new SimpleLightbox('.gallery a', {
  className: 'custom-lightbox',
  overlay: true,
  overlayOpacity: 0.8,
  captions: true,
  captionsData: 'alt',
  captionDelay: 250,
  captionPosition: 'bottom',
  closeText: `<svg><use href="${sprite}#icon-x"></use></svg>`,
  navText: [
    `<svg><use href="${sprite}#icon-left"></use></svg>`,
    `<svg><use href="${sprite}#icon-right"></use></svg>`,
  ],
});
gallery.open();
